// Configure json-bigint to handle large integers
const JSONBig = JSONBigInt({
  useNativeBigInt: true,
  alwaysParseAsBig: false,
  storeAsString: false
});

/**
 * Safely stringify a value to JSON, handling circular references and non-serializable objects.
 *
 * In MLflow users can add arbitrary values to the span attributes, however, some of them
 * cannot be represented in JSON (e.g. functions, circular references). This helper replaces
 * those values with a stable placeholder instead of throwing, so that span attribute
 * serialization never breaks the user's application.
 *
 * @param value The value to stringify
 * @returns JSON string representation of the value
 */
export function safeJsonStringify(value: any): string {
  // Track visited objects to detect circular references.
  const seen = new WeakSet<object>();

  // MLflow-specific replacer that handles functions, undefined, errors and circular refs.
  const mlflowReplacer = (_key: string, val: any): any => {
    if (typeof val === 'function') {
      return '[Function]';
    }
    if (val === undefined) {
      return '[Undefined]';
    }

    if (val instanceof Error) {
      return {
        name: val.name,
        message: val.message,
        stack: val.stack
      };
    }

    if (typeof val === 'object' && val !== null) {
      if (seen.has(val)) {
        return '[Circular]';
      }
      seen.add(val);
    }

    return val;
  };

  return JSON.stringify(value, mlflowReplacer);
}

export { JSONBig };
